result:
**The bug:** The manual expiry check uses `<` (strict less-than), so a token where `exp === Math.floor(Date.now() / 1000)` passes the check and is accepted. It should use `<=`.

**The deeper issue:** The manual check is actually dead code. `jwt.verify()` already throws `TokenExpiredError` when `exp <= currentTime`, so any token reaching the manual check is guaranteed non-expired. The real problem is the `catch` block swallows all errors with the same generic message, hiding expiry from other JWT errors.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify already rejects tokens where exp <= currentTime (including exact match)
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired', expiredAt: err.expiredAt });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid', date: err.date });
    }
    // Unexpected error (e.g. missing JWT_SECRET) — don't leak internals
    console.error('Auth middleware error:', err);
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

Key changes:
- **Removed the manual expiry check** — `jwt.verify` handles the exact-time edge case correctly via `exp <= currentTime`
- **Differentiated error types** in the catch block so clients get actionable responses (`TokenExpiredError` vs `JsonWebTokenError` vs `NotBeforeError`)
- **Added a 500 fallback** for unexpected errors (e.g. `JWT_SECRET` not set) rather than leaking internals as a 401
